    "studio.prompt-builder.blk.role.hint": "Quel rôle l'IA doit-elle jouer ? Précis et réaliste vaut mieux que « génie de classe mondiale ».",
    "studio.prompt-builder.blk.role.tpl": "Vous êtes un(e) [rôle précis] avec de l'expérience en [domaine].",
    "studio.prompt-builder.blk.task.name": "Objectif / Tâche",
    "studio.prompt-builder.blk.task.hint": "Que doit-elle produire exactement, et pourquoi ?",
